record.ownedProcessAfterStop = JSON.parse(ps(`$ErrorActionPreference='Stop';$p=Get-CimInstance Win32_Process -Filter 'ProcessId=${child.pid}';if($null -eq $p){@{absent=$true}|ConvertTo-Json -Compress}else{@{absent=$false;pid=[int]$p.ProcessId;executable=[string]$p.ExecutablePath;created=[string]$p.CreationDate}|ConvertTo-Json -Compress}`));
  record.ownedProcessAbsent = record.ownedProcessAfterStop.absent === true;
  if(!record.ownedProcessAbsent){record.ok=false;record.checks.ownedProcessAbsent='failed';}
  else record.checks.ownedProcessAbsent='passed';
  record.remainingOwnedPortListeners = listeners();
